// =================================================================
// GROUP MATCHES BY USER
// =================================================================
// WHAT: The SQL query returns one row per match (user × product).
//   A single user might match 5 different products. We need to
//   group them so we send ONE email per user listing ALL their
//   matched products, not 5 separate emails.
//
// HOW: We use a JavaScript Map to group matches by user_id.
//   For each user, we build:
//   - Their name and email
//   - A list of all their matched products
//   - An HTML email body with a nice table
//
// OUTPUT: One n8n item per USER (not per match), containing:
//   - to_email: where to send (but we override with test addresses)
//   - subject: email subject line
//   - html_body: the formatted HTML email
//   - match_ids: array of match IDs to mark as notified
// =================================================================

const userMap = new Map();

for (const item of $input.all()) {
  const d = item.json;
  const userId = d.user_id;

  if (!userMap.has(userId)) {
    userMap.set(userId, {
      user_name: d.user_name,
      user_email: d.user_email,
      products: [],
      match_ids: []
    });
  }

  const user = userMap.get(userId);
  user.products.push({
    product_name: d.product_name,
    provider: d.provider,
    interest_rate: d.interest_rate,
    match_score: d.match_score,
    match_reason: d.match_reason
  });
  user.match_ids.push(d.match_id);
}

// Build the output items — one per user
const results = [];
let testIndex = 1;

for (const [userId, userData] of userMap) {
  // Build the HTML email body
  const productRows = userData.products.map(p => `
    <tr>
      <td style="padding: 12px; border-bottom: 1px solid #eee;">${p.product_name}</td>
      <td style="padding: 12px; border-bottom: 1px solid #eee;">${p.provider}</td>
      <td style="padding: 12px; border-bottom: 1px solid #eee;">${p.interest_rate}%</td>
      <td style="padding: 12px; border-bottom: 1px solid #eee;">${Math.round(p.match_score * 100)}%</td>
    </tr>
  `).join('');

  const htmlBody = `
    <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
      <div style="background: linear-gradient(135deg, #6c5ce7, #a78bfa); padding: 24px; border-radius: 12px 12px 0 0;">
        <h1 style="color: white; margin: 0; font-size: 22px;">💰 Your Loan Matches are Ready!</h1>
      </div>
      <div style="background: white; padding: 24px; border: 1px solid #eee; border-radius: 0 0 12px 12px;">
        <p style="color: #333; font-size: 16px;">Hi <strong>${userData.user_name}</strong>,</p>
        <p style="color: #666;">Based on your profile, we've found <strong>${userData.products.length} personal loan product${userData.products.length > 1 ? 's' : ''}</strong> you may qualify for:</p>

        <table style="width: 100%; border-collapse: collapse; margin: 20px 0;">
          <thead>
            <tr style="background: #f8f9fa;">
              <th style="padding: 12px; text-align: left; border-bottom: 2px solid #ddd;">Product</th>
              <th style="padding: 12px; text-align: left; border-bottom: 2px solid #ddd;">Provider</th>
              <th style="padding: 12px; text-align: left; border-bottom: 2px solid #ddd;">Rate</th>
              <th style="padding: 12px; text-align: left; border-bottom: 2px solid #ddd;">Match</th>
            </tr>
          </thead>
          <tbody>
            ${productRows}
          </tbody>
        </table>

        <p style="color: #888; font-size: 13px; margin-top: 20px;">This is an automated notification from ClickPe Loan Eligibility Engine. Please verify eligibility directly with the provider before applying.</p>
      </div>
    </div>
  `;

  results.push({
    json: {
      user_id: userId,
      user_name: userData.user_name,
      // IMPORTANT: We do NOT use the CSV email addresses.
      // The task says: 'Use test-inbox aliases such as yourname+one@gmail.com'
      // Replace 'yourname' with your actual Gmail username below.
      to_email: userData.user_email,
      subject: `ClickPe: ${userData.products.length} Loan Product${userData.products.length > 1 ? 's' : ''} Matched for You!`,
      html_body: htmlBody,
      match_ids: userData.match_ids,
      product_count: userData.products.length
    }
  });

  // Only process first 5 users for demo (SES sandbox has sending limits)
  if (results.length >= 5) break;
}

console.log(`Prepared ${results.length} notification emails`);
return results;
